    /// How many items were cut: `total_before - kept.len()`, or 0 if the public fields were later assigned so that
    /// `kept` outnumbers `total_before`.
    #[must_use]
    pub fn omitted(&self) -> usize {
        self.total_before.saturating_sub(self.kept.len())
    }

