//! NAPI export surface for the `@orin-dx/michi` npm package (`packages/michi-node`).
//!
//! `packages/michi-node/src/lib.rs` re-exports this module (`pub use michi_core::napi::*;`) rather than defining
//! `#[napi]` items directly, so the export logic can be unit-tested here alongside the rest of the crate.
//! `packages/michi-node` remains a separate Cargo crate only because `crate-type = ["cdylib"]` cannot coexist with a
//! regular `[lib]` in one `Cargo.toml` (see "NAPI" in `docs/spec/04-mcp-and-napi.md`).
//!
//! The exports live in submodules by concern, and nothing but `num` is public: the `#[napi]` items register
//! themselves with the addon, and no Rust caller needs them by name. Each export converts its untyped JS arguments
//! through `input` (which bounds them) and then calls a private function that renders; the limits live in `input`
//! only.
//!
//! | Module | Exports |
//! | --- | --- |
//! | `toon` | `renderToon`, `renderKv`, `renderStatus` |
//! | `hints` | `renderHints`, `appendHints`, `renderRecovery` |
//! | `outcome` | `renderDomainError`, `renderAlreadyDone`, `alreadyDone`, `renderPartialSuccess`, `renderPipeline` |
//! | `resilience` | `parseRetryAfter`, `nextRetryDelay`, `isRetryableStatus`, `truncate` |
//! | `response` | the `AgentResponse` class and `toCallToolResult` |
//! | `value` | the `ToonValue` cell and `KvItem`, shared by the rest |
//!
//! Every export uses `#[napi(catch_unwind)]` so a Rust panic cannot crash the host Node.js process, and every export
//! that accepts caller-controlled collection sizes validates them against hard limits before doing any work, since a
//! single crafted call from untrusted JS is otherwise able to force unbounded synchronous allocation on Node's
//! single-threaded event loop. The byte cap also bounds the output: a render is at most 19 times the bytes held plus
//! 4 KiB, because every held byte is charged for each place a writer can put it (see `input::MAX_INPUT_BYTES` and
//! `cost`).
//!
//! This is the one module in the crate exempted from the workspace's
//! `unsafe_code = "deny"` lint (`[workspace.lints.rust]` in the root
//! `Cargo.toml`): `#[napi(catch_unwind)]` expands to macro-generated FFI glue
//! that needs `unsafe` to call into the N-API C ABI. No unsafe is hand-written
//! in this file; the only hand-written `unsafe` is in the `num` submodule's
//! `FromNapiValue`/`ToNapiValue` impls, which those napi traits require.
#![allow(unsafe_code)]
// napi-derive registers the exports only outside test builds, so in a test build they look unused.
#![cfg_attr(test, allow(dead_code))]
#![deny(
    clippy::as_conversions,
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    clippy::cast_possible_wrap,
    clippy::cast_precision_loss
)]

/// Validating newtypes for the NAPI numeric boundary (shared kernel for
/// both the rendering and resilience domains).
pub mod num;

/// What a held item can cost in output beyond its own bytes: the names a `truncated` or `totalCount` row writes again.
mod cost;
/// Bounded, incremental conversion of the exports' collection and string arguments.
mod input;

mod hints;
mod outcome;
mod resilience;
mod response;
mod toon;
mod value;

/// Render the TOON 4.4 `already_done` document: `operation`, `status: already_done`, `summary`, `help`.
///
/// # Errors
///
/// Rejects more than 10,000 hints, an `operation` over 4 KiB, a `summary` or hint over 1 MiB, and more than 16 MiB
/// of strings per call.
#[napi(
    catch_unwind,
    js_name = "renderAlreadyDone",
    ts_args_type = "operation: string, summary: string, hints: Array<string>"
)]
pub fn render_already_done(operation: Unknown<'_>, summary: Unknown<'_>, hints: Unknown<'_>) -> napi::Result<String> {
    let mut budget = Budget::new();
    let hints = List::new(hints, "hints")?;
    input::check_len("hints", hints.len(), MAX_HINTS)?;
    let operation = budget.string(operation, "operation", MAX_NAME_BYTES)?;
    let summary = budget.string(summary, "summary", MAX_STRING_BYTES)?;
    let hints: Vec<crate::hints::Hint> =
        budget.strings(&hints, "hints", MAX_HINTS, "hint", MAX_STRING_BYTES)?.into_iter().map(Into::into).collect();
    Ok(crate::resilience::render_already_done(&operation, &summary, &hints))
}

/// Render a classified `DomainError` as a TOON 4.4 document (`error`, `message`, `causes`, `exit_code`, `help`), or
/// as a GitHub Actions annotation (`::error title={code}::{message}`, without hints or causes). For its JSON or an MCP
/// result, or to report it next to data, use `AgentResponse.error()`: the same text, one JSON shape.
///
/// `causes` (optional) are why the error happened, outermost first, rendered as their own `causes[N]: …` key after the
/// message; `hints` are what to do next.
///
/// # Errors
///
/// Rejects an unknown `code`, more than 10,000 hints or causes, a `code` over 4 KiB, a `message`, hint or cause over
/// 1 MiB, and more than 16 MiB of strings per call.
#[napi(
    catch_unwind,
    js_name = "renderDomainError",
    ts_args_type = "code: 'invalid_input' | 'not_found' | 'unauthorized' | 'forbidden' | 'conflict' | 'rate_limited' | \
                    'unavailable' | 'timeout' | 'external_failure', message: string, hints: Array<string>, \
                    githubAnnotation?: boolean | undefined | null, causes?: Array<string> | undefined | null"
)]
pub fn render_domain_error(
    code: Unknown<'_>,
    message: Unknown<'_>,
    hints: Unknown<'_>,
    github_annotation: Option<bool>,
    causes: Option<Unknown<'_>>,
) -> napi::Result<String> {
    let mut budget = Budget::new();
    let hints = List::new(hints, "hints")?;
    input::check_len("hints", hints.len(), MAX_HINTS)?;
    let causes = List::optional(causes, "causes")?;
    if let Some(causes) = &causes {
        input::check_len("causes", causes.len(), MAX_HINTS)?;
    }
    let code = budget.string(code, "code", MAX_NAME_BYTES)?;
    let message = budget.string(message, "message", MAX_STRING_BYTES)?;
    let hints = budget.strings(&hints, "hints", MAX_HINTS, "hint", MAX_STRING_BYTES)?;
    let causes = match &causes {
        Some(causes) => budget.strings(causes, "causes", MAX_HINTS, "cause", MAX_STRING_BYTES)?,
        None => Vec::new(),
    };
    domain_error(&code, message, hints, github_annotation.unwrap_or(false), causes)
}

/// A `DomainError` from its code label, message and causes. Shared by `renderDomainError` and `AgentResponse.error`.
pub(super) fn build_domain_error(
    code: &str,
    message: String,
    causes: Vec<String>,
) -> napi::Result<crate::error::DomainError> {
    let code: crate::error::ErrorCode =
        code.parse().map_err(|e: crate::error::UnknownErrorCode| napi::Error::from_reason(e.to_string()))?;
    let mut err = crate::error::DomainError::new(code, message);
    for c in causes {
        err = err.cause(c);
    }
    Ok(err)
}

fn domain_error(
    code: &str,
    message: String,
    hints: Vec<String>,
    github_annotation: bool,
    causes: Vec<String>,
) -> napi::Result<String> {
    let mut err = build_domain_error(code, message, causes)?;
    for h in hints {
        err = err.hint(h);
    }

